const SERIES = { formula: 'Формулы', gt: 'GT', endurance: 'Выносливость' };
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const initials = name => name.split(' ').map(s => s[0]).slice(0, 2).join('');
const age = n => `${n} ${n % 100 >= 11 && n % 100 <= 14 ? 'лет' : n % 10 === 1 ? 'год' : n % 10 >= 2 && n % 10 <= 4 ? 'года' : 'лет'}`;
const m = (n, ctx) => ctx.money ? ctx.money(n) : `€${(n / 1e6).toLocaleString('ru-RU', { maximumFractionDigits: 2 })} млн`;
const icon = (ctx, name, size = 18) => ctx.icon ? ctx.icon(name, size) : '';
const field = (label, content) => `<div class="people-fact"><span>${label}</span><strong>${content}</strong></div>`;
const rating = (value, cls = '') => `<span class="people-rating ${cls}">${value}<small>РЕЙТИНГ</small></span>`;
const portrait = (person, large = false) => `<div class="people-avatar ${large ? 'people-avatar-large' : ''}"><span class="people-initials">${initials(person.name)}</span>${person.image ? `<img src="${person.image}" alt="${esc(person.name)}" loading="lazy">` : ''}</div>`;
const trait = ([label, type, effect]) => `<button class="people-trait people-trait-${type}" type="button" aria-expanded="false" aria-label="${esc(label)}: ${esc(effect)}">${label}<span class="people-trait-tooltip" role="tooltip">${effect}</span></button>`;
const traits = person => `<div class="people-traits">${person.traits.map(trait).join('')}</div>`;
const stat = ([label, value], size = '') => `<div class="people-stat ${size}"><div><span>${label}</span><b>${value}</b></div><div class="people-stat-track"><i style="width:${value}%" class="${value >= 90 ? 'people-stat-elite' : value < 75 ? 'people-stat-low' : ''}"></i></div></div>`;

function enhance(root) {
  root.querySelectorAll('.people-avatar img').forEach(img => { img.addEventListener('error', () => { img.hidden = true; }, { once: true }); });
  root.querySelectorAll('.people-trait').forEach(button => button.addEventListener('click', event => {
    event.stopPropagation();
    const open = button.getAttribute('aria-expanded') === 'true';
    root.querySelectorAll('.people-trait[aria-expanded="true"]').forEach(b => b.setAttribute('aria-expanded', 'false'));
    button.setAttribute('aria-expanded', String(!open));
  }));
}

function openContract(person, ctx, after = () => {}, existing = true) {
  const previous = (ctx.state.offers || {})[person.id];
  const title = existing ? 'Продление контракта' : 'Предложение контракта';
  ctx.modal({
    title,
    body: `<div class="people-contract-head">${portrait(person)}<div><h3>${person.name}</h3><p>${person.role} · ${person.team}</p></div>${rating(person.rating)}</div><p class="people-modal-copy">${existing ? 'Согласуйте условия на следующий период. Предложение сохранится в разделе «Рынок → Активные предложения».' : 'Подготовьте предложение на следующий сезон. Оно сохранится в разделе «Рынок → Активные предложения».'}</p><form id="people-offer-form"><label class="people-field">Годовая зарплата, €<input name="salary" type="number" min="100000" max="30000000" step="50000" value="${previous?.salary || Math.round(person.salary * 1.1 / 50000) * 50000}" required></label><div class="people-form-grid"><label class="people-field">Срок контракта<select name="years"><option value="1">1 сезон</option><option value="2" selected>2 сезона</option><option value="3">3 сезона</option></select></label><label class="people-field">Приоритет<select name="priority"><option>Равный статус</option><option>Лидер программы</option><option>Развитие и ротация</option></select></label></div><div class="people-offer-note">${icon(ctx, 'info', 17)}<span>Текущая зарплата: <strong>${m(person.salary, ctx)}/год</strong>. Ожидания: от ${m(Math.round(person.salary * 1.08), ctx)}.</span></div></form>`,
    footer: '<button class="btn" data-modal-close>Отмена</button><button class="btn btn-primary" type="submit" form="people-offer-form">Отправить предложение</button>',
    onMount: (root = document) => {
      enhance(root);
      const form = root.querySelector('#people-offer-form');
      form?.addEventListener('submit', event => {
        event.preventDefault();
        const data = new FormData(form);
        const offer = { name: person.name, salary: Number(data.get('salary')), years: Number(data.get('years')), priority: data.get('priority'), status: 'На рассмотрении', type: existing ? 'Продление' : 'Переход' };
        const next = { ...(ctx.state.offers || {}), [person.id]: offer };
        ctx.state.offers = next;
        ctx.setState({ offers: next });
        root.querySelector('[data-modal-close]')?.click();
        ctx.toast(`Предложение отправлено: ${person.name}`);
        after();
      });
    }
  });
}

function openProfile(person, ctx, after = () => {}, isMarket = false) {
  const offer = (ctx.state.offers || {})[person.id];
  ctx.modal({
    title: 'Досье',
    body: `<div class="people-profile"><div class="people-profile-top">${portrait(person, true)}<div class="people-profile-identity"><span class="eyebrow">${person.role}</span><h2>${person.name}</h2><p>${person.country} · ${age(person.age)}</p><span class="people-profile-team">${person.team}</span>${traits(person)}</div>${rating(person.rating)}</div><p class="people-profile-bio">${person.bio}</p><div class="people-profile-facts">${field('Контракт', `до ${person.until}`)}${field('Зарплата', `${m(person.salary, ctx)}/год`)}${field('Мораль', `${person.morale} / 100`)}${field(person.potential ? 'Потенциал' : 'Статус', person.potential ? `${person.potential} / 100` : offer ? 'Переговоры' : isMarket ? 'Доступен' : 'В команде')}</div><div class="people-section-title"><h3>Характеристики</h3><span>0–100</span></div><div class="people-profile-skills">${person.skills.map(s => stat(s)).join('')}</div><div class="people-section-title"><h3>Карьера</h3><span>${person.history.length} записи</span></div><div class="people-career">${person.history.map(h => `<div><span>${h[0]}</span><strong>${h[1]}</strong><small>${h[2]}</small></div>`).join('')}</div>${isMarket && person.series !== 'formula' && person.kind === 'drivers' ? '<div class="people-offer-note">Переход в формулы: потребуется адаптация к аэродинамике и открытым колёсам.</div>' : ''}</div>`,
    footer: `<button class="btn" data-modal-close>Закрыть</button><button class="btn btn-primary" id="people-contract-open">${offer ? 'Изменить предложение' : isMarket ? 'Предложить контракт' : 'Продлить контракт'}</button>`,
    onMount: (root = document) => {
      enhance(root);
      root.querySelector('#people-contract-open')?.addEventListener('click', () => openContract(person, ctx, after, !isMarket));
    }
  });
}

function openCompare(persons, ctx) {
  if (persons.length !== 2) return;
  const [a, b] = persons;
  const labels = [...new Set([...a.skills, ...b.skills].map(s => s[0]))];
  ctx.modal({
    title: 'Сравнение',
    body: `<div class="people-compare-head">${persons.map(p => `<div>${portrait(p)}<h3>${p.name}</h3><p>${p.role}</p>${rating(p.rating)}</div>`).join('')}</div><div class="people-compare-rows">${labels.map(label => { const av = a.skills.find(s => s[0] === label)?.[1]; const bv = b.skills.find(s => s[0] === label)?.[1]; return `<div class="people-compare-row"><strong class="${av > bv ? 'people-winning' : ''}">${av ?? '—'}</strong><span>${label}</span><strong class="${bv > av ? 'people-winning' : ''}">${bv ?? '—'}</strong></div>`; }).join('')}<div class="people-compare-row"><strong>${a.age}</strong><span>Возраст</span><strong>${b.age}</strong></div><div class="people-compare-row"><strong>${m(a.salary, ctx)}</strong><span>Зарплата / год</span><strong>${m(b.salary, ctx)}</strong></div></div><div class="people-compare-traits">${persons.map(p => `<div>${traits(p)}</div>`).join('')}</div>`,
    footer: '<button class="btn btn-primary" data-modal-close>Закрыть сравнение</button>',
    onMount: (root = document) => enhance(root)
  });
}

export function mountPeople(container, ctx) {
  const requestedPerson = PEOPLE.find(p => p.id === ctx.state.selectedPerson);
  let tab = requestedPerson?.kind || 'drivers', query = '', sorting = 'rating', contractFilter = 'all';
  const selected = new Set();
  const render = () => {
    const matches = PEOPLE.filter(p => p.kind === tab && `${p.name} ${p.role} ${p.country}`.toLowerCase().includes(query.toLowerCase()) && (contractFilter !== 'ending' || p.until === 2028)).sort((a, b) => sorting === 'age' ? a.age - b.age : sorting === 'name' ? a.name.localeCompare(b.name, 'ru') : b.rating - a.rating);
    container.innerHTML = `<section class="people-screen"><div class="screen-head"><div><span class="eyebrow">VANTA RACING / КОМАНДА</span><h1>Пилоты и персонал</h1><p>Пилоты, инженеры и характеры за результатом.</p></div><button class="btn" data-market>${icon(ctx, 'scan-search')} Открыть рынок</button></div><div class="people-summary"><div><span class="people-summary-icon">${icon(ctx, 'users')}</span><span>Основной состав<strong>2 пилота · 3 руководителя</strong></span></div><div><span class="people-summary-icon">${icon(ctx, 'heart-pulse')}</span><span>Атмосфера в команде<strong class="people-positive">Стабильная · 88/100</strong></span></div><div><span class="people-summary-icon">${icon(ctx, 'calendar-clock')}</span><span>Контракты до конца сезона<strong>Вебер, Бергер</strong></span></div></div><div class="people-tabs" role="tablist" aria-label="Состав команды">${[['drivers','Пилоты','02'], ['staff','Персонал','03'], ['academy','Академия','02']].map(([id, label, count]) => `<button role="tab" aria-selected="${tab === id}" class="${tab === id ? 'is-active' : ''}" data-tab="${id}">${label}<span>${count}</span></button>`).join('')}</div><div class="people-toolbar"><label class="people-search">${icon(ctx, 'search')}<input type="search" aria-label="Поиск по команде" placeholder="Имя, должность, страна" value="${esc(query)}"></label><select aria-label="Фильтр контрактов" data-contract-filter><option value="all" ${contractFilter === 'all' ? 'selected' : ''}>Все контракты</option><option value="ending" ${contractFilter === 'ending' ? 'selected' : ''}>Истекают в 2028</option></select><select aria-label="Сортировка состава" data-sort><option value="rating" ${sorting === 'rating' ? 'selected' : ''}>По рейтингу</option><option value="age" ${sorting === 'age' ? 'selected' : ''}>По возрасту</option><option value="name" ${sorting === 'name' ? 'selected' : ''}>По имени</option></select><button class="btn people-compare-btn" data-compare ${selected.size !== 2 ? 'disabled' : ''}>${icon(ctx, 'columns-2')} Сравнить <span>${selected.size}/2</span></button></div><div class="people-cards ${tab === 'staff' ? 'people-staff-grid' : ''}">${matches.map(p => personCard(p, ctx, selected)).join('') || '<div class="people-empty"><h3>Никого не нашли</h3><p>Попробуйте другое имя или измените фильтр контрактов.</p><button class="btn" data-reset-filters>Сбросить фильтры</button></div>'}</div>${tab === 'drivers' ? '<div class="people-bottom-note"><span>СОСТАВ НА ЭТАП</span><p>Келлер и Вебер заявлены на ГП Лазурного берега. Резервные места доступны через академию и рынок.</p></div>' : tab === 'academy' ? '<div class="people-bottom-note"><span>ПРОГРАММА РАЗВИТИЯ</span><p>Общий мир объединяет дисциплины. Пилоты академии могут продолжить карьеру в формулах, GT и гонках на выносливость.</p></div>' : ''}</section>`;
    enhance(container);
    container.querySelector('[data-market]').onclick = () => ctx.navigate('market');
    container.querySelectorAll('[data-tab]').forEach(b => b.onclick = () => { tab = b.dataset.tab; selected.clear(); render(); });
    const search = container.querySelector('input[type="search"]');
    search.addEventListener('input', () => { const pos = search.selectionStart; query = search.value; render(); const next = container.querySelector('input[type="search"]'); next.focus(); try { next.setSelectionRange(pos, pos); } catch {} });
    container.querySelector('[data-sort]').onchange = e => { sorting = e.target.value; render(); };
    container.querySelector('[data-contract-filter]').onchange = e => { contractFilter = e.target.value; render(); };
    container.querySelector('[data-reset-filters]')?.addEventListener('click', () => { query = ''; contractFilter = 'all'; render(); });
    container.querySelectorAll('[data-profile]').forEach(b => b.onclick = () => openProfile(PEOPLE.find(p => p.id === b.dataset.profile), ctx, render));
    container.querySelectorAll('[data-select-person]').forEach(b => b.onchange = () => { const id = b.dataset.selectPerson; if (selected.has(id)) selected.delete(id); else if (selected.size < 2) selected.add(id); else ctx.toast('Для сравнения выберите двух человек'); render(); });
    container.querySelector('[data-compare]').onclick = () => openCompare(PEOPLE.filter(p => selected.has(p.id)), ctx);
    container.querySelectorAll('[data-contract]').forEach(b => b.onclick = () => openContract(PEOPLE.find(p => p.id === b.dataset.contract), ctx, render));
  };
  render();
  if (ctx.state.selectedPerson) { ctx.setState({ selectedPerson: null }); if (requestedPerson) openProfile(requestedPerson, ctx, render); }
  return () => {};
}

function personCard(p, ctx, selected) {
  const offer = (ctx.state.offers || {})[p.id];
  return `<article class="people-person-card panel"><div class="people-person-top ${p.kind === 'staff' ? 'people-person-staff' : ''}"><div class="people-person-photo">${portrait(p, true)}${p.number ? `<span class="people-car-number">${p.number}</span>` : ''}</div><div class="people-person-info"><span class="eyebrow">${p.role}</span><button class="people-name-button" data-profile="${p.id}"><h2>${p.name}</h2></button><p>${p.country} <span>·</span> ${age(p.age)}</p>${p.kind !== 'staff' ? `<div class="people-race-record"><strong>${p.position}<small>МЕСТО</small></strong><strong>${p.points}<small>ОЧКОВ</small></strong>${p.potential ? `<strong>${p.potential}<small>ПОТЕНЦИАЛ</small></strong>` : ''}</div>` : `<div class="people-staff-morale"><span>Мораль</span><strong>${p.morale}/100</strong></div>`}</div>${rating(p.rating)}</div><div class="people-person-content">${traits(p)}<div class="people-card-skills">${p.skills.slice(0, 4).map(s => stat(s, 'people-stat-compact')).join('')}</div><div class="people-card-contract"><span>Контракт <strong>до ${p.until}</strong></span><span>${m(p.salary, ctx)}<small>/год</small></span></div>${offer ? '<div class="people-offer-status">Предложение на рассмотрении</div>' : p.until === 2028 ? `<button class="people-contract-warning" data-contract="${p.id}">${icon(ctx, 'clock', 15)} Контракт заканчивается в этом сезоне <span>Продлить</span></button>` : ''}</div><footer class="people-card-footer"><label><input type="checkbox" data-select-person="${p.id}" ${selected.has(p.id) ? 'checked' : ''}> Сравнить</label><button class="people-profile-link" data-profile="${p.id}">Открыть досье ${icon(ctx, 'chevron-right', 16)}</button></footer></article>`;
}

const SUPPLIERS = [
  { id: 'vanta-vp6', name: 'VP6 Hybrid', maker: 'VANTA Powertrain', type: 'engine', tag: 'Текущий поставщик', cost: 14500000, power: 91, reliability: 84, efficiency: 88, detail: 'Гибридная силовая установка · пакет на сезон', contract: 'Действует до 2029', availability: '4 команды-клиента' },
  { id: 'helix-h6', name: 'HELIX H6 Evo', maker: 'Helix Engineering', type: 'engine', tag: 'Доступно с 2029', cost: 14300000, power: 94, reliability: 84, efficiency: 90, detail: 'Гибридная силовая установка · пакет на сезон', contract: 'Переговоры открыты', availability: '1 свободный контракт' },
  { id: 'asterion-a6', name: 'ASTERION A6', maker: 'Asterion Motorsport', type: 'engine', tag: 'Доступно с 2029', cost: 10800000, power: 83, reliability: 95, efficiency: 84, detail: 'Гибридная силовая установка · пакет на сезон', contract: 'Переговоры открыты', availability: '2 свободных контракта' },
  { id: 'vanta-gt8', name: 'GT8 Sequential', maker: 'VANTA Powertrain', type: 'gearbox', tag: 'Текущий поставщик', cost: 2400000, power: 86, reliability: 92, efficiency: 90, detail: '8-ступенчатая коробка · поддержка и запасные части', contract: 'Действует до 2029', availability: 'Совместима с V28' },
  { id: 'atlas-x8', name: 'ATLAS X8', maker: 'Atlas Transmission', type: 'gearbox', tag: 'Доступно с 2029', cost: 2450000, power: 93, reliability: 88, efficiency: 92, detail: '8-ступенчатая коробка · поддержка и запасные части', contract: 'Переговоры открыты', availability: 'Требуется интеграция' }
];

export function mountMarket(container, ctx) {
  let tab = 'drivers', query = '', discipline = 'all', sort = 'rating';
  let compare = new Set();
  function render() {
    const supplierTab = tab === 'suppliers';
    const candidates = CANDIDATES.filter(p => (tab === 'staff' ? p.kind === 'staff' : p.kind === 'drivers') && (discipline === 'all' || p.series === discipline || p.series === 'all') && `${p.name} ${p.team} ${p.role}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => sort === 'salary' ? a.salary - b.salary : sort === 'age' ? a.age - b.age : b.rating - a.rating);
    const suppliers = SUPPLIERS.filter(p => `${p.name} ${p.maker}`.toLowerCase().includes(query.toLowerCase()));
    const offers = Object.keys(ctx.state.offers || {}).length + Object.keys(ctx.state.supplierOffers || {}).length;
    container.innerHTML = `<section class="market-screen"><div class="screen-head"><div><span class="eyebrow">МОТОРСПОРТ / РЫНОК</span><h1>Рынок и поставщики</h1><p>Найдите людей и технологии, которые изменят вашу команду.</p></div><span class="market-offers-counter">${icon(ctx, 'messages-square')} Переговоры <b>${offers}</b></span></div><div class="people-tabs market-tabs" role="tablist" aria-label="Рынок">${[['drivers','Пилоты'],['staff','Персонал'],['suppliers','Поставщики']].map(([id,label]) => `<button role="tab" aria-selected="${tab===id}" class="${tab===id?'is-active':''}" data-market-tab="${id}">${label}</button>`).join('')}</div><div class="people-toolbar"><label class="people-search">${icon(ctx,'search')}<input type="search" aria-label="Поиск на рынке" placeholder="${supplierTab ? 'Название или производитель' : 'Имя, команда, специализация'}" value="${esc(query)}"></label>${!supplierTab ? `<select data-market-discipline aria-label="Дисциплина"><option value="all" ${discipline==='all'?'selected':''}>Все дисциплины</option>${Object.entries(SERIES).map(([key,value])=>`<option value="${key}" ${discipline===key?'selected':''}>${value}</option>`).join('')}</select><select data-market-sort aria-label="Сортировка рынка"><option value="rating" ${sort==='rating'?'selected':''}>По рейтингу</option><option value="salary" ${sort==='salary'?'selected':''}>По зарплате</option><option value="age" ${sort==='age'?'selected':''}>По возрасту</option></select><button class="btn" data-market-compare ${compare.size!==2?'disabled':''}>${icon(ctx,'columns-2')} Сравнить ${compare.size}/2</button>` : '<span class="market-regulation-note">Сезон поставок · 2029</span>'}</div>${supplierTab ? `<div class="market-suppliers">${suppliers.map(p => supplierCard(p,ctx)).join('')}</div>` : `<div class="market-table panel"><div class="market-table-header"><span>Кандидат</span><span>Рейтинг</span><span>Зарплата / год</span><span>Контракт</span><span>Действия</span></div>${candidates.map(p=>candidateRow(p,ctx,compare)).join('') || '<div class="people-empty"><h3>Нет подходящих кандидатов</h3><p>Измените запрос или выберите все дисциплины.</p></div>'}</div>`}<div class="market-bottom"><div class="market-scouting-note">${icon(ctx,'scan-eye',22)}<div><strong>${supplierTab ? 'Правила поставок' : 'Отчёт скаутов обновлён'}</strong><p>${supplierTab ? 'Контракты заключаются на следующий сезон. Смена силовой установки учитывается в программе разработки автомобиля.' : 'Показаны изученные кандидаты. Переход между дисциплинами сохраняет опыт пилота и требует адаптации к новой технике.'}</p></div></div>${offers ? `<button class="btn" data-show-offers>Активные предложения · ${offers}</button>` : ''}</div></section>`;
    enhance(container);
    container.querySelectorAll('[data-market-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.marketTab;query='';compare.clear();render();});
    const input = container.querySelector('input[type="search"]');
    input.oninput=()=>{const p=input.selectionStart;query=input.value;render();const i=container.querySelector('input[type="search"]');i.focus();try{i.setSelectionRange(p,p);}catch{}};
    container.querySelector('[data-market-discipline]')?.addEventListener('change',e=>{discipline=e.target.value;render();});
    container.querySelector('[data-market-sort]')?.addEventListener('change',e=>{sort=e.target.value;render();});
    container.querySelectorAll('[data-candidate-profile]').forEach(b=>b.onclick=()=>openProfile(CANDIDATES.find(p=>p.id===b.dataset.candidateProfile),ctx,render,true));
    container.querySelectorAll('[data-candidate-offer]').forEach(b=>b.onclick=()=>openContract(CANDIDATES.find(p=>p.id===b.dataset.candidateOffer),ctx,render,false));
    container.querySelectorAll('[data-market-check]').forEach(b=>b.onchange=()=>{const id=b.dataset.marketCheck;if(compare.has(id))compare.delete(id);else if(compare.size<2)compare.add(id);else ctx.toast('Можно сравнить двух кандидатов');render();});
    container.querySelector('[data-market-compare]')?.addEventListener('click',()=>openCompare(CANDIDATES.filter(p=>compare.has(p.id)),ctx));
    container.querySelectorAll('[data-supplier-offer]').forEach(b=>b.onclick=()=>openSupplier(SUPPLIERS.find(p=>p.id===b.dataset.supplierOffer),ctx,render));
    container.querySelector('[data-show-offers]')?.addEventListener('click',()=>showOffers(ctx));
  }
  render();
  return () => {};
}

function candidateRow(p,ctx,selected) {
  const offer = (ctx.state.offers||{})[p.id];
  return `<article class="market-candidate"><div class="market-candidate-identity"><label class="market-check-label"><input type="checkbox" aria-label="Сравнить: ${p.name}" data-market-check="${p.id}" ${selected.has(p.id)?'checked':''}></label>${portrait(p)}<div><button data-candidate-profile="${p.id}">${p.name}</button><p>${age(p.age)} · ${p.country}</p><span>${p.team} <em>${SERIES[p.series]||'Инженерия'}</em></span></div></div><div class="market-cell-rating"><span class="market-mobile-label">Рейтинг</span><strong>${p.rating}</strong></div><div class="market-cell-salary"><span class="market-mobile-label">Зарплата</span><strong>${m(p.salary,ctx)}</strong><small>ожидает от ${m(Math.round(p.salary*1.08),ctx)}</small></div><div class="market-cell-contract"><span class="market-mobile-label">Контракт</span><strong>до ${p.until}</strong><small>Открыт к переговорам</small></div><div class="market-cell-action"><button class="btn ${offer?'':'btn-primary'}" data-candidate-offer="${p.id}">${offer?'На рассмотрении':'Предложение'}</button></div><div class="market-candidate-traits">${traits(p)}</div></article>`;
}

function supplierCard(p,ctx) {
  const offer=(ctx.state.supplierOffers||{})[p.id];
  const current=p.tag==='Текущий поставщик';
  return `<article class="market-supplier-card panel"><div class="market-supplier-top"><span class="market-supplier-icon">${icon(ctx,p.type==='engine'?'cog':'settings-2',28)}</span><span class="market-supplier-tag ${current?'is-current':''}">${offer?'Запрос отправлен':p.tag}</span></div><span class="eyebrow">${p.maker}</span><h2>${p.name}</h2><p class="market-supplier-description">${p.detail}</p><div class="market-supplier-stats">${stat([p.type==='engine'?'Мощность':'Переключение',p.power])}${stat(['Надёжность',p.reliability])}${stat(['Эффективность',p.efficiency])}</div><div class="market-supplier-price"><strong>${m(p.cost,ctx)}</strong><span>за сезон</span></div><footer><span>${p.availability}</span><button class="btn ${current?'':'btn-primary'}" data-supplier-offer="${p.id}">${current?'Условия':offer?'Открыть запрос':'Запросить условия'}</button></footer></article>`;
}

function openSupplier(p,ctx,after) {
  const current=p.tag==='Текущий поставщик';
  ctx.modal({title:p.name,body:`<div class="market-supplier-detail"><span class="eyebrow">${p.maker}</span><h2>${current?'Контракт на поставку':'Новая программа поставок'}</h2><p>${p.detail}</p><div class="people-profile-facts">${field('Стоимость / сезон',m(p.cost,ctx))}${field('Начало',current?'2028':'2029')}${field('Поддержка','На каждом этапе')}${field('Статус',p.contract)}</div><div class="people-offer-note">В пакет входят ${p.type==='engine'?'силовые установки, обновления калибровок и инженерная поддержка':'коробки передач, запасные части и поддержка интеграции'}. Условия действуют для программы Formula.</div><label class="people-field">Срок поставки<select id="market-supplier-years"><option value="1">1 сезон</option><option value="2" selected>2 сезона</option><option value="3">3 сезона</option></select></label></div>`,footer:`<button class="btn" data-modal-close>Закрыть</button>${current?'':'<button class="btn btn-primary" id="market-supplier-submit">Запросить предложение</button>'}`,onMount:(root=document)=>{root.querySelector('#market-supplier-submit')?.addEventListener('click',()=>{const years=Number(root.querySelector('#market-supplier-years').value);const supplierOffers={...(ctx.state.supplierOffers||{}),[p.id]:{name:p.name,years,cost:p.cost,status:'Запрос отправлен'}};ctx.state.supplierOffers=supplierOffers;ctx.setState({supplierOffers});root.querySelector('[data-modal-close]')?.click();ctx.toast(`Запрос отправлен в ${p.maker}`);after();});}});
}

function showOffers(ctx) {
  const offers=[...Object.values(ctx.state.offers||{}),...Object.values(ctx.state.supplierOffers||{}).map(o=>({...o,type:'Поставка',salary:o.cost}))];
  ctx.modal({title:'Активные переговоры',body:`<div class="people-offer-list">${offers.map(o=>`<div><strong>${esc(o.name)}</strong><span>${esc(o.type)} · ${o.years} сезона</span><b>${m(o.salary,ctx)}/год</b><small>${esc(o.status)}</small></div>`).join('')}</div>`,footer:'<button class="btn btn-primary" data-modal-close>Закрыть</button>'});
}

